			this.onstop?.();
		}
	}
	globalThis.MediaRecorder = FakeRecorder;
	globalThis.window = { MediaRecorder: FakeRecorder };
	const stream = () => {
		let stops = 0;
		const value = {
			getTracks: () => [{ stop: () => (stops += 1) }],
			stops: () => stops,
		};
		streams.push(value);
		return value;
	};
