	class Select {
		constructor() {
			this.dataset = {};
			this.options = [];
			this.value = "";
			this.disabled = false;
		}
		set textContent(value) {
			if (value === "") this.options = [];
		}
		get textContent() {
			return this.options.map((option) => option.textContent).join("");
		}
		appendChild(option) {
			this.options.push(option);
		}
	}
