        let base = if self.provider.is_empty() {
            self.model.clone()
        } else {
            format!("{}/{}", self.provider, self.model)
        };
        if base.is_empty() {
            return base;
        }
        if self.thinking.is_empty() {
            base
        } else {
            format!("{}:{}", base, self.thinking)
        }
    }
    pub fn spoken(&self) -> String {
        format!(
            "{}{}{}",
            self.model,
            if self.provider.is_empty() {
                String::new()
            } else {
                format!(" on {}", self.provider)
            },
            if self.thinking.is_empty() {
