			type: recorder.mimeType || "audio/webm",
		});
		const id = globalThis.crypto?.randomUUID
			? globalThis.crypto.randomUUID()
			: `${Date.now()}-${++clipSequence}`;
		const clip = {
			id,
			audio: blob,
